import{getEntireSurahService,getSpesificSurahService}from"../../../../services/surah.services.js";import{ErrorHandler}from"../../../../libraries/errors/_errors.js";const getEntireSurahController=async(req,res,next)=>{const getEntireSurah=await getEntireSurahService(req.query);return res.status(200).json({success:true,message:req.ext.constants.MESSAGE_DATA_RETRIEVED,data:getEntireSurah})};const getSpesificSurahController=async(req,res,next)=>{const getSpesificSurah=await getSpesificSurahService(req.params.surah,req.query);if(!getSpesificSurah){throw new ErrorHandler({code:404,details:[{path:["surah"],message:`We cannot find surah sequence '${req.params.surah}'.`}],message:"NOT_FOUND"})}return res.status(200).json({success:true,message:req.ext.constants.MESSAGE_DATA_RETRIEVED,data:getSpesificSurah})};const getSpesificSurahAyahController=async(req,res,next)=>{const getSpesificSurah=await getSpesificSurahService(req.params.surah,req.query);if(!getSpesificSurah){throw new ErrorHandler({code:404,details:[{path:["surah"],message:`We cannot find surah sequence '${req.params.surah}'.`}],message:"NOT_FOUND"})}const getSpesificAyahSurah=new Map(getSpesificSurah.ayah.map(ayah=>[ayah.sequence.surah,ayah])).get(req.params.ayah);if(!getSpesificAyahSurah){throw new ErrorHandler({code:404,details:[{path:["ayah"],message:`We cannot find ayah sequence '${req.params.ayah}' in surah '${req.params.surah}'.`}],message:"NOT_FOUND"})}const surahFormatted={...getSpesificSurah,ayah:getSpesificAyahSurah};return res.status(200).json({success:true,message:req.ext.constants.MESSAGE_DATA_RETRIEVED,data:surahFormatted})};export{getEntireSurahController,getSpesificSurahAyahController,getSpesificSurahController};